function sanitizeNpcProfile(value: unknown): DesignerNpcProfile | undefined {
  if (!value || typeof value !== "object") {
    return undefined;
  }

  const candidate = value as Partial<DesignerNpcProfile>;
  const movementIntervalMinSeconds =
    typeof candidate.movementIntervalMinSeconds === "number" &&
    Number.isFinite(candidate.movementIntervalMinSeconds) &&
    candidate.movementIntervalMinSeconds > 0
      ? Math.round(candidate.movementIntervalMinSeconds)
      : DEFAULT_NPC_MOVEMENT_INTERVAL_MIN;
  const movementIntervalMaxSeconds =
    typeof candidate.movementIntervalMaxSeconds === "number" &&
    Number.isFinite(candidate.movementIntervalMaxSeconds) &&
    candidate.movementIntervalMaxSeconds > 0
      ? Math.max(
          movementIntervalMinSeconds,
          Math.round(candidate.movementIntervalMaxSeconds)
        )
      : DEFAULT_NPC_MOVEMENT_INTERVAL_MAX;
  const movementStepMin =
    typeof candidate.movementStepMin === "number" &&
    Number.isFinite(candidate.movementStepMin) &&
    candidate.movementStepMin > 0
      ? Math.round(candidate.movementStepMin)
      : DEFAULT_NPC_MOVEMENT_STEP_MIN;
  const movementStepMax =
    typeof candidate.movementStepMax === "number" &&
    Number.isFinite(candidate.movementStepMax) &&
    candidate.movementStepMax > 0
      ? Math.max(movementStepMin, Math.round(candidate.movementStepMax))
      : DEFAULT_NPC_MOVEMENT_STEP_MAX;

  return {
    aiType: isNpcAiType(candidate.aiType) ? candidate.aiType : "standing",
    npcType: isNpcType(candidate.npcType) ? candidate.npcType : "healer",
    graphicsSource: isNpcGraphicsSource(candidate.graphicsSource)
      ? candidate.graphicsSource
      : "custom",
    characterSkinId:
      typeof candidate.characterSkinId === "string" ? candidate.characterSkinId.trim() : "",
    characterSkinName:
      typeof candidate.characterSkinName === "string"
        ? normalizeCategoryName(candidate.characterSkinName)
        : "",
    movementIntervalMinSeconds,
    movementIntervalMaxSeconds,
    movementStepMin,
    movementStepMax,
    scriptSource: typeof candidate.scriptSource === "string" ? candidate.scriptSource : "",
    healPrice:
      typeof candidate.healPrice === "number" &&
      Number.isFinite(candidate.healPrice) &&
      candidate.healPrice >= 0
        ? Math.round(candidate.healPrice)
        : DEFAULT_NPC_HEAL_PRICE,
    trainerPokemons: sanitizeNpcTrainerPokemons(candidate.trainerPokemons),
    storeMoney:
      typeof candidate.storeMoney === "number" &&
      Number.isFinite(candidate.storeMoney) &&
      candidate.storeMoney >= 0
        ? Math.round(candidate.storeMoney)
        : DEFAULT_NPC_STORE_MONEY,
    storeItems: sanitizeNpcStoreItems(candidate.storeItems),
    chestSlotCapacity:
      typeof candidate.chestSlotCapacity === "number" &&
      Number.isFinite(candidate.chestSlotCapacity) &&
      candidate.chestSlotCapacity > 0
        ? Math.round(candidate.chestSlotCapacity)
        : DEFAULT_NPC_CHEST_SLOTS,
    chestItems: sanitizeNpcChestItems(candidate.chestItems),
    graphics: sanitizeNpcGraphicsProfile(candidate.graphics),
  };
}

function sanitizeSkillGfxProfile(value: unknown): DesignerSkillGfxProfile | undefined {
  if (!value || typeof value !== "object") {
    return undefined;
  }

  const candidate = value as Partial<DesignerSkillGfxProfile>;
  const positiveNumber = (input: unknown) =>
    typeof input === "number" && Number.isFinite(input) && input > 0
      ? Math.round(input)
      : undefined;
  const integer = (input: unknown) =>
    typeof input === "number" && Number.isFinite(input) ? Math.round(input) : undefined;

  return {
    mediaSrc: typeof candidate.mediaSrc === "string" ? candidate.mediaSrc : "",
    applyTo: isSkillGfxApplyTo(candidate.applyTo) ? candidate.applyTo : "selected foe",
    appear:
      typeof candidate.appear === "number" && Number.isFinite(candidate.appear) && candidate.appear > 0
        ? Math.round(candidate.appear)
        : 1,
    essentialsAnimationId: integer(candidate.essentialsAnimationId),
    essentialsAnimationIndex: integer(candidate.essentialsAnimationIndex),
    essentialsAnimationName:
      typeof candidate.essentialsAnimationName === "string" ? candidate.essentialsAnimationName : "",
    animationKind: isMoveAnimationKind(candidate.animationKind) ? candidate.animationKind : "other",
    graphic: typeof candidate.graphic === "string" ? candidate.graphic : "",
    sourcePath: typeof candidate.sourcePath === "string" ? candidate.sourcePath : "",
    outputPath: typeof candidate.outputPath === "string" ? candidate.outputPath : "",
    sheetSourcePath: typeof candidate.sheetSourcePath === "string" ? candidate.sheetSourcePath : "",
    sheetOutputPath: typeof candidate.sheetOutputPath === "string" ? candidate.sheetOutputPath : "",
    sourceWidth: positiveNumber(candidate.sourceWidth),
    sourceHeight: positiveNumber(candidate.sourceHeight),
    cellSize: positiveNumber(candidate.cellSize),
    columns: positiveNumber(candidate.columns),
    rows: positiveNumber(candidate.rows),
    frameCount: positiveNumber(candidate.frameCount),
    fps: positiveNumber(candidate.fps),
    durationMs: positiveNumber(candidate.durationMs),
    hue: integer(candidate.hue),
    position: integer(candidate.position),
    speed: positiveNumber(candidate.speed),
    warnings: Array.isArray(candidate.warnings)
      ? candidate.warnings.filter((item): item is string => typeof item === "string")
      : [],
    linkedMoveIds: Array.isArray(candidate.linkedMoveIds)
      ? candidate.linkedMoveIds.filter((item): item is string => typeof item === "string")
      : [],
    source: candidate.source,
  };
}

function sanitizePokemonSkillProfile(
  value: unknown,
  fallbackItem?: Pick<DesignerItemSeed, "category" | "details">
): DesignerPokemonSkillProfile | undefined {
  const candidate =
    value && typeof value === "object"
      ? (value as Partial<DesignerPokemonSkillProfile> & {
          element?: unknown;
          type?: unknown;
          types?: unknown;
        })
      : null;
  const elements = resolvePokemonElements(candidate, fallbackItem);
  const weatherEffect = candidate?.weatherEffect;
  const fallbackValue = (label: string) =>
    fallbackItem?.details.find((item) => item.label === label)?.value ?? "";
  const candidateCategory = candidate?.category;

  if (!candidate && !fallbackItem) {
    return undefined;
  }

  return {
    elements: elements.length > 0 ? elements : [POKEMON_ELEMENTS[0]],
    power:
      typeof candidate?.power === "number" && Number.isFinite(candidate.power) && candidate.power >= 0
        ? Math.round(candidate.power)
        : parseSkillNonNegativeNumber(fallbackValue("Power")) ?? 0,
    powerPoint:
      typeof candidate?.powerPoint === "number" &&
      Number.isFinite(candidate.powerPoint) &&
      candidate.powerPoint > 0
        ? Math.round(candidate.powerPoint)
        : parsePokemonDetailNumber(fallbackItem?.details ?? [], "Power Point", 1),
    accuracy:
      typeof candidate?.accuracy === "number" && Number.isFinite(candidate.accuracy) && candidate.accuracy > 0
        ? Math.round(candidate.accuracy)
        : parsePokemonDetailNumber(fallbackItem?.details ?? [], "Accuracy", 100),
    category: isMoveDamageClass(candidateCategory)
      ? candidateCategory
      : isMoveDamageClass(fallbackValue("Damage Class"))
        ? fallbackValue("Damage Class")
        : "Physical",
    target: typeof candidate?.target === "string" && candidate.target.trim().length > 0
      ? candidate.target.trim()
      : fallbackValue("Target") || "NearOther",
    functionCode:
      typeof candidate?.functionCode === "string" && candidate.functionCode.trim().length > 0
        ? candidate.functionCode.trim()
        : fallbackValue("Function Code") || "None",
    flags: normalizeMoveFlags(candidate?.flags ?? fallbackValue("Flags")),
    priority:
      typeof candidate?.priority === "number" && Number.isFinite(candidate.priority)
        ? Math.round(candidate.priority)
        : parseSkillInteger(fallbackValue("Priority")) ?? 0,
    description: typeof candidate?.description === "string" ? candidate.description : "",
    effectText: typeof candidate?.effectText === "string" ? candidate.effectText : "",
    skillGfxId: typeof candidate?.skillGfxId === "string" ? candidate.skillGfxId : "",
    skillGfxName: typeof candidate?.skillGfxName === "string" ? candidate.skillGfxName : "",
    animationId: typeof candidate?.animationId === "string" ? candidate.animationId : "",
    animationName: typeof candidate?.animationName === "string" ? candidate.animationName : "",
    weatherEffect: isWeatherEffect(weatherEffect)
      ? weatherEffect
      : WEATHER_EFFECT_OPTIONS[0],
    inflictStateId: typeof candidate?.inflictStateId === "string" ? candidate.inflictStateId : "",
    inflictStateName: typeof candidate?.inflictStateName === "string" ? candidate.inflictStateName : "",
    cooldown:
      typeof candidate?.cooldown === "number" &&
      Number.isFinite(candidate.cooldown) &&
      candidate.cooldown >= 0
        ? Math.round(candidate.cooldown)
        : 0,
    stateConditionId:
      typeof candidate?.stateConditionId === "string" ? candidate.stateConditionId : "",
    stateConditionName:
      typeof candidate?.stateConditionName === "string" ? candidate.stateConditionName : "",
  };
}

function sanitizePlayableMapConfig(
  value: unknown,
  regionNames: string[]
): DesignerPlayableMapConfig | undefined {
  if (!value || typeof value !== "object") {
    return undefined;
  }

  const candidate = value as Partial<DesignerPlayableMapConfig>;
  const cellSize =
    typeof candidate.cellSize === "number" && MAP_CELL_SIZE_OPTIONS.includes(candidate.cellSize as 8 | 16 | 32 | 64 | 128)
      ? candidate.cellSize
      : null;
  const width =
    typeof candidate.width === "number" && Number.isFinite(candidate.width) && candidate.width > 0
      ? Math.max(1, Math.round(candidate.width))
      : null;
  const height =
    typeof candidate.height === "number" && Number.isFinite(candidate.height) && candidate.height > 0
      ? Math.max(1, Math.round(candidate.height))
      : null;
  const regionName =
    typeof candidate.regionName === "string" && candidate.regionName.trim().length > 0
      ? candidate.regionName.trim()
      : regionNames[0] ?? "";

  if (
    cellSize === null ||
    width === null ||
    height === null ||
    !isValidMapSizePreset(candidate.sizePreset) ||
    !isValidPlayableMapType(candidate.mapType)
  ) {
    return undefined;
  }

  return {
    ...candidate,
    cellSize,
    sizePreset: candidate.sizePreset,
    width,
    height,
    isInitialMap: candidate.isInitialMap === true,
    initialPositionX:
      typeof candidate.initialPositionX === "number" && Number.isFinite(candidate.initialPositionX)
        ? Math.round(candidate.initialPositionX)
        : null,
    initialPositionY:
      typeof candidate.initialPositionY === "number" && Number.isFinite(candidate.initialPositionY)
        ? Math.round(candidate.initialPositionY)
        : null,
    regionName,
    regionX:
      typeof candidate.regionX === "number" && Number.isFinite(candidate.regionX)
        ? Math.round(candidate.regionX)
        : 0,
    regionY:
      typeof candidate.regionY === "number" && Number.isFinite(candidate.regionY)
        ? Math.round(candidate.regionY)
        : 0,
    mapType: candidate.mapType,
    backgroundColor: normalizeBackgroundColor(candidate.backgroundColor ?? ""),
    backgroundImageSrc:
      typeof candidate.backgroundImageSrc === "string"
        ? candidate.backgroundImageSrc
        : "",
    backgroundImageMode: isValidBackgroundImageMode(candidate.backgroundImageMode)
      ? candidate.backgroundImageMode
      : DEFAULT_MAP_BACKGROUND_IMAGE_MODE,
  };
}

function normalizeInitialPlayableMapItems(items: DesignerItemSeed[]) {
  let hasInitialMap = false;

  return items.map((item) => {
    if (!item.playableMapConfig) {
      return item;
    }

    const isInitialMap = item.playableMapConfig.isInitialMap === true && !hasInitialMap;

    if (isInitialMap) {
      hasInitialMap = true;
    }

    return {
      ...item,
      playableMapConfig: {
        ...item.playableMapConfig,
        isInitialMap,
      },
    };
  });
}

function syncPlayableMapItems(items: DesignerItemSeed[]) {
  const normalizedItems = normalizeInitialPlayableMapItems(items);

  return normalizedItems.map((item, index) =>
    item.playableMapConfig
      ? {
          ...item,
          details: designerSectionsByKey.mapsEditor.createDetails(
            item.name,
            item.category,
            index + 1,
            { playableMapConfig: item.playableMapConfig }
          ),
        }
      : item
  );
}

function loadRegionNames() {
  const fallbackRegions =
    buildInitialState("regions").items.map((item) => item.name).filter(Boolean);

  if (typeof window === "undefined") {
    return fallbackRegions;
  }

  try {
    const raw =
      window.localStorage.getItem(getDesignerSectionStorageKey("regions")) ??
      window.localStorage.getItem(getLegacyDesignerSectionStorageKey("regions"));
    if (!raw) {
      return fallbackRegions;
    }

    const parsed = JSON.parse(raw) as Partial<DesignerSectionState> & { state?: Partial<DesignerSectionState> };
    const regionState = parsed.state ?? parsed;
    const regionNames = Array.isArray(regionState.items)
      ? regionState.items
          .map((item) => (typeof item?.name === "string" ? item.name.trim() : ""))
          .filter(Boolean)
      : [];

    return regionNames.length > 0 ? regionNames : fallbackRegions;
  } catch {
    return fallbackRegions;
  }
}

function buildInitialState(sectionKey: DesignerSectionKey): DesignerSectionState {
  const section = designerSectionsByKey[sectionKey];
  const categorySet = new Set([UNCATEGORIZED, ...section.defaultCategories]);

  return {
    categories: Array.from(categorySet),
    items: [],
  };
}

function sanitizeSectionState(
  sectionKey: DesignerSectionKey,
  value: unknown
): DesignerSectionState {
  const fallback = buildInitialState(sectionKey);
  const regionNames = loadRegionNames();

  if (!value || typeof value !== "object") {
    return fallback;
  }

  const parsed = value as Partial<DesignerSectionState>;
  if (!Array.isArray(parsed.categories) || !Array.isArray(parsed.items)) {
    return fallback;
  }

  const categories = Array.from(
    new Set(
      [UNCATEGORIZED, ...parsed.categories]
        .map((category) => normalizeCategoryName(category))
        .filter(Boolean)
    )
  );

  const items = parsed.items
    .filter(
      (item): item is DesignerItemSeed =>
        typeof item?.id === "string" &&
        typeof item?.name === "string" &&
        typeof item?.category === "string" &&
        Array.isArray(item?.details)
    )
    .map((item) => ({
      ...item,
      category: normalizeCategoryName(item.category) || UNCATEGORIZED,
      itemProfile:
        sectionKey === "items"
          ? sanitizeGameItemProfile(item.itemProfile)
          : undefined,
      mapObjectAsset: sanitizeMapObjectAsset(item.mapObjectAsset),
      playableMapConfig: sanitizePlayableMapConfig(item.playableMapConfig, regionNames),
      skillGfxProfile:
        sectionKey === "skillsGfx"
          ? sanitizeSkillGfxProfile(item.skillGfxProfile)
          : undefined,
      npcProfile:
        sectionKey === "npcs"
          ? sanitizeNpcProfile(item.npcProfile)
          : undefined,
      characterSkinProfile:
        sectionKey === "players"
          ? sanitizeCharacterSkinProfile(item.characterSkinProfile)
          : undefined,
      pokemonProfile:
        sectionKey === "pokemons"
          ? sanitizePokemonProfile(item.pokemonProfile, item)
          : undefined,
      pokemonSkillProfile:
        sectionKey === "skills"
          ? sanitizePokemonSkillProfile(item.pokemonSkillProfile, item)
          : undefined,
    }));
  const normalizedItems =
    sectionKey === "mapsEditor" ? syncPlayableMapItems(items) : items;

  normalizedItems.forEach((item) => categories.push(item.category));

  return {
    categories: Array.from(new Set(categories)),
    items: normalizedItems,
  };
}

// Delegates to the shared designer cache (memory first, then localStorage):
// heavy sections (assets, tilesets, battleBackgrounds) exceed the storage
// quota and only ever exist in the memory cache, seeded by the HTTP download.
function readStoredPayload(sectionKey: DesignerSectionKey): StoredDesignerSectionPayload {
  const payload = readStoredDesignerSectionPayload(sectionKey);

  return {
    ...payload,
    state: sanitizeSectionState(sectionKey, payload.state),
  };
}

// Patches with more ops than this are bulk operations (imports, full
// replaces) and fall back to the whole-state save path.
const PATCH_OPS_EMIT_LIMIT = 80;

// Computes item-level ops between two section states. Relies on the
// immutable-update convention (unchanged items keep their identity), so a
// normal add/edit/delete/move produces a handful of ops while a bulk import
// naturally overflows the limit and falls back to a full save.
function diffSectionStatesToOps(
  previous: DesignerSectionState,
  next: DesignerSectionState
): DesignerSectionPatchOp[] {
  const ops: DesignerSectionPatchOp[] = [];
  const categoriesChanged =
    previous.categories !== next.categories &&
    (previous.categories.length !== next.categories.length ||
      previous.categories.some((category, index) => category !== next.categories[index]));

  if (categoriesChanged) {
    ops.push({ kind: "setCategories", categories: next.categories });
  }

  const previousById = new Map(previous.items.map((item) => [item.id, item]));
  const nextIds = new Set<string>();

  for (const item of next.items) {
    nextIds.add(item.id);
    const previousItem = previousById.get(item.id);

    if (!previousItem || previousItem !== item) {
      ops.push({ kind: "upsert", item });
    }
  }

  for (const item of previous.items) {
    if (!nextIds.has(item.id)) {
      ops.push({ kind: "delete", itemId: item.id });
    }
  }

  return ops;
}

function loadStoredState(sectionKey: DesignerSectionKey): DesignerSectionState {
  return readStoredPayload(sectionKey).state;
}

function persistStoredPayload(
  sectionKey: DesignerSectionKey,
  payload: StoredDesignerSectionPayload
) {
  if (typeof window === "undefined") {
    return;
  }

  persistStoredDesignerSectionPayload(sectionKey, payload);
}

function buildImportedSectionState(
  sectionKey: DesignerSectionKey,
  value: unknown
): DesignerSectionState | null {
  if (Array.isArray(value)) {
    return sanitizeSectionState(sectionKey, {
      categories: [],
      items: value,
    });
  }

  if (!value || typeof value !== "object") {
    return null;
  }

  const candidate = value as Record<string, unknown>;
  const nestedValue =
    "state" in candidate
      ? candidate.state
      : "data" in candidate
        ? candidate.data
        : value;

  if (nestedValue !== value) {
    return buildImportedSectionState(sectionKey, nestedValue);
  }

  if (!Array.isArray(candidate.items)) {
    return null;
  }

  return sanitizeSectionState(sectionKey, {
    categories: Array.isArray(candidate.categories) ? candidate.categories : [],
    items: candidate.items,
  });
}

